import{z as o,x as A,o as e,c as d,q as r,j as n,D as E,d as i,s as B,S as l}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"债券流动性与 TRACE","description":"","frontmatter":{"title":"债券流动性与 TRACE","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bond-liquidity-trace.md","filePath":"quant/bond-liquidity-trace.md","lastUpdated":1791063341000}'),s={name:"quant/bond-liquidity-trace.md"};function p(C,a,m,h,c,u){const t=A("Mermaid");return e(),d("div",null,[a[2]||(a[2]=r('<h1 id="债券流动性与-trace" tabindex="-1">债券流动性与 TRACE <a class="header-anchor" href="#债券流动性与-trace" aria-label="Permalink to &quot;债券流动性与 TRACE&quot;">​</a></h1><div class="epigraph"><p>公司债的「价差」很少挂成连续的买卖报价。公开可观测的往往是事后报告的成交，流动性度量必须从打印里重建，而不是从一张股票式的限价簿里读取。</p><footer>—— Bessembinder, Maxwell and Venkataraman；Edwards, Harris and Piwowar, Corporate Bond Market Transaction Costs and Transparency, Journal of Finance, 2007</footer></div><p><a href="/quant/convertible-credit">可转债与信用混合</a>把转债写成股票加信用的定价核，默认你能看到一个可用的债底价格。本课的缺口是：普通公司债没有股票那样的连续 <a href="/quant/lob-structure">LOB</a>，流动性写在 OTC 成交里。TRACE（Trade Reporting and Compliance Engine）把美国公司债成交强制报告，使交易成本第一次可以按打印来估。Edwards、Harris 与 Piwowar 以及 Bessembinder 等人表明，透明度提高后交易成本下降，但债券仍远比股票「不连续」。后课 OTC 询价写交易如何发生；本课写 TRACE 作为流动性度量的数据契约。附录 <a href="/quant/trace-corporate-bond">TRACE 成交报告</a>会把字段与延迟写细，本课不重复报文手册。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>股票价差分解依赖 BBO。公司债多数时间没有可比较的公开双向报价，或者报价是经销商对特定客户的指示性价格，不是可对全市场执行的承诺。能观测的是：哪只债、何时、什么价格、多大面值、买方是否对经销商，以及报告是否被上限截断。流动性问题于是改写为：从不规则、带截断、带延迟的成交打印中，估计往返成本、价格冲击与变现时间。把股票的有效价差公式原样套上，会缺中点；硬用相邻成交价差当价差，会把信用评级迁移的跳价当成摩擦。</p><p><span class="marginnote">术语翻译：BBO（最佳买卖报价）是股票屏幕顶上那条「当前最高买价加最低卖价」——一条随时可按价成交的公开承诺。债券多数时候没有这条线，只有成交之后才补报的打印，所以说债券市场的透明是「事前暗、事后亮」。</span></p><p>TRACE 的引入本身是制度实验：事前仍暗、事后更亮。研究要区分「报告规则改变了行为」与「报告让我们第一次看见旧行为」。Edwards–Harris–Piwowar 处理的是透明度与成本，不是把债券变成股票微观结构的副本。</p><h3 id="没有中点时有效价差怎么定义" tabindex="-1">没有中点时有效价差怎么定义 <a class="header-anchor" href="#没有中点时有效价差怎么定义" aria-label="Permalink to &quot;没有中点时有效价差怎么定义&quot;">​</a></h3><p>常用代理：对同一只债、同一天、接近的买卖打印做配对，估经销商的买卖加价；或用基准曲线（国债或 CDS）的理论价当参照，成交相对理论价的偏离当「有效价差」。前者需要方向或经销商标识，后者把模型和流动性混在一起——曲线本身含流动性溢价。本课允许两套，但必须声明。不要发明一个全日中点再跑 Lee–Ready：债券日内成交可能只有几笔，中点是虚构的。</p><p><span class="marginnote">数字实例：同一只债，上午 10:05 出现客户卖给经销商的打印 98.20，10:40 出现客户从经销商买入的打印 98.65——两次成交之间的经销商加价约 0.45 个点，这就是配对法估出的往返成本。若当天只有单向成交，配对法用不上，只能退回基准偏离法。</span></p>',10)),(e(),n(l,null,{default:E(()=>[B(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%B8%80%E7%AC%94%20TRACE%20%E6%88%90%E4%BA%A4%E6%89%93%E5%8D%B0%22%5D%20--%3E%20D%7B%22%E6%9C%89%E6%97%A0%E6%96%B9%E5%90%91%E4%B8%8E%E7%BB%8F%E9%94%80%E5%95%86%E6%A0%87%E8%AF%86%22%7D%0A%20%20D%20--%3E%7C%22%E6%9C%89%22%7C%20PAIR%5B%22%E9%85%8D%E5%AF%B9%E6%B3%95%EF%BC%9A%E5%90%8C%E6%97%A5%E7%9B%B8%E8%BF%91%E4%B9%B0%E5%8D%96%E6%89%93%E5%8D%B0%E4%BC%B0%E5%8A%A0%E4%BB%B7%22%5D%0A%20%20D%20--%3E%7C%22%E6%97%A0%22%7C%20BENCH%7B%22%E5%9F%BA%E5%87%86%E6%B3%95%EF%BC%9A%E9%80%89%E5%8F%82%E7%85%A7%22%7D%0A%20%20BENCH%20--%3E%20GS%5B%22%E5%9B%BD%E5%80%BA%E6%88%96%E5%90%8C%E8%AF%84%E7%BA%A7%E5%9F%BA%E5%87%86%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20BENCH%20--%3E%20CDS%5B%22CDS%20%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20GS%20--%3E%20DEV%5B%22%E6%88%90%E4%BA%A4%E4%BB%B7%E7%9B%B8%E5%AF%B9%E5%8F%82%E7%85%A7%E7%9A%84%E5%81%8F%E7%A6%BB%E5%8D%B3%E6%9C%89%E6%95%88%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20CDS%20--%3E%20DEV%0A%20%20PAIR%20--%3E%20CK%5B%22%E5%8F%A3%E5%BE%84%E5%A3%B0%E6%98%8E%EF%BC%9A%E6%9B%B2%E7%BA%BF%E6%9C%AC%E8%BA%AB%E5%90%AB%E6%B5%81%E5%8A%A8%E6%80%A7%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20DEV%20--%3E%20CK%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">TRACE 对大额成交曾有金额上限与延迟披露。用截断后的面值去加权成本，会系统性低估机构大单的冲击。应使用未截断研究数据集（若许可）或对上限成交单独分层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按债券、按日构建：成交笔数、成交面值、价格极差、相对基准的偏离、以及滚动若干日的Amihud 式 \\(|r|/\\mathrm{volume}\\)。债券的「量」是面值不是股数。持有期匹配：投资级活跃券可能日频有打印，高收益冷门券可以几天没有成交，变现时间见<a href="/quant/liquidity-horizon">流动性地平线</a>，不要用零成交日的 ILLIQ 当无穷。事件研究用评级调整、发行、指数纳入，看打印频率与成本的变化。</p><p>与股票度量对照时，只对照<strong>同地平线</strong>的对象：日度债券 ILLIQ 对日度股票 ILLIQ，而不是对五分钟实现价差。Huang–Stoll 式三路分解在债券上通常不可估，因为没有连续方向结构。两笔成交的价差更接近处理加存货加搜索成本。</p><h3 id="透明度、存货与匹配质量" tabindex="-1">透明度、存货与匹配质量 <a class="header-anchor" href="#透明度、存货与匹配质量" aria-label="Permalink to &quot;透明度、存货与匹配质量&quot;">​</a></h3><p>事后报告提高了客户对「别人成交在哪」的可见性，削弱经销商的信息租金，这是 Edwards–Harris–Piwowar 的机制方向。经销商仍提供存货与搜索：客户不是对着一张簿吃单，而是打电话或发 RFQ。TRACE 打印是匹配的结果，不是簿的状态。因此债券「深度」不能从打印反推成股票 L2。能做的是：给定面值 \\(Q\\)，估计额外成本如何随 \\(Q\\) 上升，用分层成交规模来代理冲击——这是粗糙的，但诚实。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>公司债流动性差的结构原因是：异质契约（条款、期权、担保）、持有人分散、违约跳跃使逆向选择昂贵、以及缺少统一的连续匹配。TRACE 改变的是事后透明，不自动产生事前 BBO。价格发现大量发生在 CDS 与股票里，债券打印是滞后确认。把债券收益的短时自相关当 Roll 价差，可能把稀少成交之间的新闻当成摩擦。应先用基准调整残差，再谈债券自身的流动性成分。</p><p><span class="marginnote">不要把 <a href="/quant/kyle-model">Kyle</a> 的连续时间做市直接校准到一天两笔的债券上。经验 lambda 需要流量；没有流量时，lambda 的分母不稳定。冷门券应改报变现时间，而不是报一个爆炸的 \\(\\hat\\lambda\\)。</span></p>',9)),(e(),n(l,null,{default:E(()=>[B(t,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20LR%0A%20%20T%5B%22TRACE%20%E6%89%93%E5%8D%B0%22%5D%20--%3E%20C%5B%22%E8%A7%84%E6%A8%A1%E5%88%86%E5%B1%82%E6%88%90%E6%9C%AC%22%5D%0A%20%20T%20--%3E%20I%5B%22%E6%97%A5%E5%BA%A6%20ILLIQ%20%2F%20%E6%9E%81%E5%B7%AE%22%5D%0A%20%20B%5B%22%E5%9F%BA%E5%87%86%E6%9B%B2%E7%BA%BF%E6%88%96%20CDS%22%5D%20--%3E%20D%5B%22%E7%9B%B8%E5%AF%B9%E5%9F%BA%E5%87%86%E5%81%8F%E7%A6%BB%22%5D%0A%20%20C%20--%3E%20L%5B%22%E5%80%BA%E5%88%B8%E6%B5%81%E5%8A%A8%E6%80%A7%E5%BA%A6%E9%87%8F%22%5D%0A%20%20I%20--%3E%20L%0A%20%20D%20--%3E%20L%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h3 id="冷门券的对象是变现时间不是-lambda" tabindex="-1">冷门券的对象是变现时间不是 lambda <a class="header-anchor" href="#冷门券的对象是变现时间不是-lambda" aria-label="Permalink to &quot;冷门券的对象是变现时间不是 lambda&quot;">​</a></h3><p>一天两笔的债券，分母流量不稳定，经验 lambda 会爆炸或接近零。应报「在给定冲击上限下需要多少个交易日」，与流动性地平线课对齐，而不是硬输出一个 \\(\\hat\\lambda\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>美国公司债 TRACE 不能代表中国银行间、欧洲公司债或贷款。市政债、ABS 有自己的报告系统。可转债同时在股票与债券通道交易，流动性是混合的，不要只用 TRACE 打印去估转债冲击。下一课进入 OTC 询价协议本身：RFQ、经销商网络、以及为什么同一打印价格对另一客户不可执行。</p><p><span class="marginnote">常见误区：把「两天没成交」读成流动性无穷差。零成交说明的是「没人来交易」，不是「成本无穷高」；正确的报告是把问题改写成变现时间——「在可接受的冲击内卖完这笔面值需要几个交易日」，而不是报一个分母不稳、会爆掉的流动性系数。</span></p><p><span class="marginnote">可转债同时走股票通道与债券打印。只用 TRACE 估冲击，会漏掉转股与正股对冲腿上的流动性。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>公司债流动性主要从 TRACE 一类事后打印重建，不是从 LOB 读取。</li><li>有效价差需要配对成交或相对基准偏离；不要虚构连续中点。</li><li>大额截断与延迟披露会偏倚规模加权成本。</li><li>透明度降低信息租金，不自动创造连续深度。</li><li>冷门券应报变现时间，而不是硬估 lambda。</li><li>出处：Edwards, Harris and Piwowar, <em>Journal of Finance</em>, 2007；Bessembinder, Maxwell and Venkataraman 对 TRACE 与交易成本的研究；Harris 对债券市场结构的讨论。</li></ul>',8))])}const b=o(s,[["render",p]]);export{D as __pageData,b as default};
